/*
 * cdrom/cd-replay-doom3600fast - generated by tools/cdreplayexe.js (do not edit: regenerate) from doom-plan.json, frames 3600-3900, 3863
 * accesses. A game's CD conversation replayed with its own spacing: each access at the trace's delay after the interrupt it
 * followed. Every read, interrupt time and DMA header goes to RAM; all printed after the last access. Bounded waits (rule 1).
 * THE RULE: run it here first (hwtests/run.js), then on a console through the queue.
 */
#include <common.h>
#include <psxapi.h>
#include <io.h>
#include <stdio.h>
#include <timer.h>
#include "replay.h"

static volatile uint8_t *CDR[4] = { (volatile uint8_t *)0x1F801800, (volatile uint8_t *)0x1F801801,
                                    (volatile uint8_t *)0x1F801802, (volatile uint8_t *)0x1F801803 };
static void idx(uint8_t i) { *CDR[0] = i & 3; }
static uint8_t irqFlag() { idx(1); return *CDR[3] & 7; }
static void ackAll() { idx(1); *CDR[3] = 0x1F; }
static bool hasResp() { return (*CDR[0] & 0x20) != 0; }
static void drain() { for (int k = 0; k < 32 && hasResp(); k++) { idx(1); (void)*CDR[1]; } }
static uint32_t clk8; static uint16_t lastT;
static inline uint32_t now() { uint16_t t = readTimer(2); clk8 += (uint16_t)(t - lastT); lastT = t; return clk8 * 8; }
static uint8_t waitAny(uint32_t limit) { uint32_t t0 = now(); for (;;) { uint8_t f = irqFlag(); if (f) return f; if (now() - t0 > limit) return 0; } }
static void cmd(uint8_t c, int nparam, const uint8_t *p, int ints) {
    idx(0); for (int k = 0; k < nparam; k++) *CDR[2] = p[k];
    idx(0); *CDR[1] = c;
    for (int k = 0; k < ints; k++) { if (!waitAny(67737600)) break; drain(); ackAll(); }
}
static uint32_t sink[600];
static uint32_t keep[REPLAY_SLOTS ? REPLAY_SLOTS * REPLAY_SLOT : 1]; static uint32_t nkept;
static void cdDma(uint32_t *to, uint32_t words) {
    write32(0x1F8010F0, read32(0x1F8010F0) | 0x00008000);
    write32(0x1F8010B0, (uint32_t)to & 0x1FFFFFFF);
    write32(0x1F8010B4, words ? words : 1);
    write32(0x1F8010B8, 0x11000000);
    for (uint32_t k = 0; (read32(0x1F8010B8) & 0x01000000) && k < 2000000; k++) { (void)now(); }
}
/* the log: one 32-bit word per access that yields something (R: value, I: cycles, D: three words) */
static uint32_t logw[REPLAY_N * 3 + 8]; static uint32_t nlog;

int main() {
    printf("\ncdrom/%s\n", REPLAY_NAME);
    EnterCriticalSection();
    const uint32_t cdDelay0 = read32(0x1F801018), comDelay0 = read32(0x1F801020);
#if SET_CD_DELAY
    write32(0x1F801018, REPLAY_CD_DELAY);
#endif
#if SET_COM_DELAY
    write32(0x1F801020, REPLAY_COM_DELAY);
#endif
    idx(1); *CDR[2] = 0; ackAll(); drain();
    uint16_t prevT = initTimer(2, 2); lastT = readTimer(2); clk8 = 0;
#if PRE_INIT
    cmd(0x0A, 0, 0, 2); cmd(0x0C, 0, 0, 1);
#endif
#if PRE_MODE
    { uint8_t m = REPLAY_MODE; cmd(0x0E, 1, &m, 1); }
#endif
#if PRE_SEEK
    if (REPLAY_HAS_LOC) { cmd(0x02, 3, REPLAY_LOC, 1); cmd(0x15, 0, 0, 2); }
#endif
    { uint32_t t0 = now(); while (now() - t0 < 16934400u) {} }
    drain(); ackAll();
    uint32_t anchor = now(), lastI = anchor;
    for (int j = 0; j < REPLAY_N; j++) {
        const Acc &a = REPLAY[j];
        if (a.k == 2) {                                   /* the interrupt: wait for the drive's own, bounded */
            uint32_t limit = 3 * a.delay + 67737600u, t0 = now(), at = 0; bool got = false;
            for (;;) { if (irqFlag()) { at = now(); got = true; break; } if (now() - t0 > limit) break; }
            if (got) { logw[nlog++] = at - lastI; anchor = at; lastI = at; }
            else { logw[nlog++] = 0xFFFFFFFFu; anchor = now(); lastI = anchor; }
            continue;
        }
        while ((int32_t)(now() - (anchor + a.delay)) < 0) {}
        idx(a.reg >> 2);
        if (a.k == 0) *CDR[a.reg & 3] = a.val;
        else if (a.k == 1) logw[nlog++] = *CDR[a.reg & 3];
        else { uint32_t *to = nkept < REPLAY_SLOTS ? keep + REPLAY_SLOT * nkept++ : sink; cdDma(to, a.val); logw[nlog++] = to[0]; logw[nlog++] = to[1]; logw[nlog++] = to[2]; }
    }
    /* the log, after the last access */
    uint32_t p = 0; int col = 0; char line[160]; int lp = 0;
    auto put = [&](const char *s) { while (*s && lp < 150) line[lp++] = *s++; };
    auto hexv = [&](uint32_t v, int digits) { const char *h = "0123456789abcdef"; for (int d = digits - 1; d >= 0; d--) line[lp++] = h[(v >> (4 * d)) & 15]; };
    auto dec = [&](uint32_t v) { char b[12]; int k = 0; do { b[k++] = '0' + v % 10; v /= 10; } while (v); while (k) line[lp++] = b[--k]; };
    auto endTok = [&]() { if (++col == 8) { line[lp] = 0; printf("%s\n", line); lp = 0; col = 0; } else line[lp++] = ' '; };
    uint32_t dk = 0;
    for (int j = 0; j < REPLAY_N; j++) {
        const Acc &a = REPLAY[j];
        if (a.k == 0) continue;
        if (a.k == 1) { put("r"); dec(a.reg); put(":"); hexv(logw[p++], 2); }
        else if (a.k == 2) { uint32_t v = logw[p++]; if (v == 0xFFFFFFFFu) put("iX"); else { put("i"); dec(v); } }
        else {
            put("d"); hexv(logw[p++], 8); put("."); hexv(logw[p++], 8); put("."); hexv(logw[p++], 8);
            if (dk < nkept) { uint32_t h = 2166136261u; const uint32_t *w = keep + REPLAY_SLOT * dk; for (uint32_t k = 0; k < a.val; k++) { h ^= w[k]; h *= 16777619u; } put("."); hexv(h, 8); }
            dk++;
        }
        endTok();
    }
    if (lp) { line[lp] = 0; printf("%s\n", line); }
    restoreTimer(2, prevT);
    write32(0x1F801018, cdDelay0); write32(0x1F801020, comDelay0);
    ExitCriticalSection();
    printf("\nDone.\n");
    for (;;) {}   /* park after Done. (a program that returns leaves Unirom deaf) */
}
